(A/'js/guide.js').write_text(r'''async function guide(){try{const d=await(await fetch('assets/data/results.json')).json();const e=await(await fetch('assets/data/exploratory.json')).json();document.getElementById('pedpyEvidence').textContent=`IMPTC ${d.pedpy.source_track_counts.IMPTC.toLocaleString()} tracks / ${d.pedpy.recordings.IMPTC} sequences, inD ${d.pedpy.source_track_counts.inD.toLocaleString()} tracks / ${d.pedpy.recordings.inD} recordings를 기술 분석했습니다. 이 수치는 저장된 실제 집계이며 독립적으로 식별된 사람 수는 아닙니다.`;const b=d.R_proxy.train_fit.bias_m,R=d.R_proxy.train_fit.covariance_m2;document.getElementById('rEvidence').textContent='\\[b_R=\\begin{bmatrix}'+b.map(v=>v.toFixed(6)).join('\\\\')+'\\end{bmatrix}m,\\quad R=\\begin{bmatrix}'+R.map(r=>r.map(v=>v.toFixed(6)).join('&')).join('\\\\')+'\\end{bmatrix}m^2\\]';const off=d.official,rr=d.position_comparison.find(r=>r.dataset==='IMPTC'&&r.mode==='rq'),ind=e.summary.find(r=>r.phase==='test'&&r.dataset==='inD'&&r.method==='selected_calibrated');document.getElementById('actualEvidence').innerHTML=`<article><small>실제 · 공식 IMPTC Test</small><strong>${off.ADE_top1_m.toFixed(6)}m ADE</strong><p>${off.sample_count.toLocaleString()} windows · FDE ${off.FDE_top1_m.toFixed(6)}m</p></article><article><small>실제 · 공식 전체 Test의 위치 포함률</small><strong>${(100*off.coverage['0.68'].all_horizons).toFixed(2)}% / ${(100*off.coverage['0.95'].all_horizons).toFixed(2)}%</strong><p>각각 목표 68% / 95% 영역의 Coverage</p></article><article><small>실제 · 작은 IMPTC R 스트레스 subset</small><strong>${(rr['coverage0.95']*100).toFixed(1)}% · ${rr['area0.95'].toFixed(2)}m²</strong><p>Legacy R+Q의 95% Coverage와 면적 · ${rr.n_windows} origins / ${rr.events} events. 높은 Coverage만으로 성공이라 할 수 없습니다.</p></article><article><small>실제 · 추가 분석, 기본 모델 미교체</small><strong>${(ind.Coverage95*100).toFixed(2)}% Coverage95</strong><p>inD 보정 후 99 origins / 11 tracks. 목표 95%에 미달했고 추가 모델 탐색을 종료했습니다.</p></article>`;window.GUIDE_DATA_READY=true;}catch(e){document.getElementById('actualEvidence').textContent='실제 집계 읽기 실패: '+e.message;window.GUIDE_DATA_ERROR=e.message;}if(typeof renderMathInElement==='function')renderMathInElement(document.body,{delimiters:[{left:'\\[',right:'\\]',display:true}],throwOnError:true,strict:'warn'});}document.addEventListener('DOMContentLoaded',guide);''')
